 38→func (a *openCodeAgent) IsTransientError(out Output, _ error) bool {
 39→	transientPatterns := []string{
 40→		"overloaded",
 41→		"rate limit",
 42→		"529",
 43→		"503",
 44→		"ECONNRESET",
 45→		"ETIMEDOUT",
 46→		"Token refresh failed",
 47→		"database is locked",
 48→	}
 49→	for _, p := range transientPatterns {
 50→		if strings.Contains(out.Stderr, p) {
 51→			return true
 52→		}
 53→	}
 54→	return false
 55→}
